   for pattern,c in enumerate(counts):
    for _ in range(c):
     for j in range(n):
      if pattern>>j&1:masks[j]|=1<<coord
     coord+=1
   found[target]=masks;print('FOUND',masks,flush=True);json.dump(found,open('workspace/agent4_venn_seeds.json','w'))
  s.pop()

